npm run adapter && mkdir -p test && cat > test/host.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };
test('lifecycle to completed', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal(await h.run('a'), null);
  assert.deepEqual(await h.start('a'), ok);
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal((await h.taskStarted('a', 3)).ok, false);
  assert.equal((await h.taskStarted('a', -1)).ok, false);
  assert.equal((await h.taskCompleted('a', 0)).ok, false);
  for (const i of [0, 1, 2]) assert.deepEqual(await h.taskStarted('a', i), ok);
  assert.equal((await h.run('a')).status, 'running');
  for (const i of [0, 1, 2]) assert.deepEqual(await h.taskEvicted('a', i), ok);
  assert.equal((await h.run('a')).status, 'evicted');
  await h.taskRequeued('a', 0);
  assert.equal((await h.run('a')).status, 'running');
  await h.taskRequeued('a', 1); await h.taskRequeued('a', 2);
  assert.equal((await h.run('a')).status, 'queued');
